-- Generated by PI Co-Pilot after a successful release: the plain-text PI columns are retired.
-- Each column is dropped only while it still exists (PI Co-Pilot may have dropped it already) and only
-- if its "_enc" copy exists and holds a value wherever the plain column does. Values are not decrypted
-- here, so a stale copy is not detected; PI Co-Pilot checks every copy before it drops a column itself.

-- drop public.employees.last_name
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'employees' AND column_name = 'last_name') THEN
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'employees' AND column_name = 'last_name_enc') THEN
            RAISE EXCEPTION 'public.employees.last_name_enc is missing; not dropping last_name';
        END IF;
        IF EXISTS (SELECT 1 FROM "public"."employees" WHERE "last_name" IS NOT NULL AND "last_name_enc" IS NULL) THEN
            RAISE EXCEPTION 'public.employees.last_name_enc is not populated; run PI Co-Pilot Data Sync before dropping last_name';
        END IF;
        ALTER TABLE "public"."employees" DROP COLUMN "last_name";
    END IF;
END $$;
